create or replace view IDQ_PRODUCTION.EKS_CALCULATION.SRWRF_MATGRP_SKU_EKS_ITEM_ZLEGACYNODE_01(
	ZITEM_BA,
	ZLEGACYNODE
) as
SELECT        EKS_CALCULATION.STMARA_EKS_ITEM.zITEM_BA, MAX(IFNULL(stEKS_ITEMGRPTIMELINE_PARENT.SHORTDESC || '.' ||  (REPEAT(0, 3 - length(EKS.ITEMGRPTIMELINE.SHORTDESC)) || EKS.ITEMGRPTIMELINE.SHORTDESC), '')) AS zLegacyNODE
FROM            EKS.ITEMGRPTIMELINE INNER JOIN
                         EKS.ITEMGROUPITEMREL ON EKS.ITEMGRPTIMELINE.ITEMGROUPID = EKS.ITEMGROUPITEMREL.ITEMGROUPID INNER JOIN
                         EKS.ITEMGRPTIMELINE as stEKS_ITEMGRPTIMELINE_PARENT ON EKS.ITEMGRPTIMELINE.PARENTID = stEKS_ITEMGRPTIMELINE_PARENT.ITEMGROUPID
                         AND GETDATE() BETWEEN EKS.ITEMGROUPITEMREL.DATEFROM AND EKS.ITEMGROUPITEMREL.DATEUNTIL
                         AND GETDATE() BETWEEN EKS.ITEMGRPTIMELINE.DATEFROM AND EKS.ITEMGRPTIMELINE.DATEUNTIL
                         AND GETDATE() BETWEEN stEKS_ITEMGRPTIMELINE_PARENT.DATEFROM AND stEKS_ITEMGRPTIMELINE_PARENT.DATEUNTIL INNER JOIN
                         EKS_CALCULATION.STMARA_EKS_ITEM ON EKS.ITEMGROUPITEMREL.ITEMID = EKS_CALCULATION.STMARA_EKS_ITEM.ITEMID
WHERE        (EKS_CALCULATION.STMARA_EKS_ITEM.BITFLAG = 0) AND (EKS_CALCULATION.STMARA_EKS_ITEM.zActive = 1)
GROUP BY EKS_CALCULATION.STMARA_EKS_ITEM.zITEM_BA
HAVING        (COUNT(DISTINCT IFNULL(stEKS_ITEMGRPTIMELINE_PARENT.SHORTDESC || '.' || (REPEAT(0, 3 - length(EKS.ITEMGRPTIMELINE.SHORTDESC)) || EKS.ITEMGRPTIMELINE.SHORTDESC), '')) = 1);